154	    /**
155	     * Counts the owners that already exist (before the current create) whose first and last names
156	     * both match the supplied names, compared case-insensitively. The returned value is captured on
157	     * the new owner at creation time and does not change as further owners are added later.
158	     *
159	     * @param firstName the new owner's first name
160	     * @param lastName  the new owner's last name
161	     * @return the number of pre-existing namesake owners
162	     */
163	    private int namesakeCount(String firstName, String lastName) {
164	        return (int) this.clinicService.findAllOwners().stream()
165	            .filter(existing -> existing.getFirstName() != null
166	                && existing.getFirstName().equalsIgnoreCase(firstName)
167	                && existing.getLastName() != null
168	                && existing.getLastName().equalsIgnoreCase(lastName))
169	            .count();
170	    }
171	
172	    /**
173	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where
174	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN}
175	     * is a global 4-digit zero-padded sequence equal to one more than the current number of
176	     * owners (e.g. {@code 'SMI-0007'}).
177	     *
178	     * @param lastName the owner's last name
179	     * @return the assigned customer code
180	     */
181	    private String nextCustomerCode(String lastName) {
182	        String prefix = (lastName == null ? "" : lastName);
183	        prefix = prefix.substring(0, Math.min(3, prefix.length())).toUpperCase(java.util.Locale.ROOT);
184	        long sequence = this.clinicService.findAllOwners().size() + 1L;
185	        return String.format("%s-%04d", prefix, sequence);
186	    }
187	
188	    /**
189	     * Normalizes a street address applied whenever an owner is created: leading and trailing
190	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
191	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
192	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
193	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
194	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
195	     * {@code '12 MAIN STREET'}.
196	     *
197	     * @param address the raw address as submitted, or {@code null} when absent
198	     * @return the normalized address, or the empty string when the value is blank
199	     */
200	    private String normalizeAddress(String address) {
201	        String collapsed = (address == null ? "" : address)
202	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
203	        if (collapsed.isEmpty()) {
204	            return "";
205	        }
206	        String[] tokens = collapsed.split(" ");
207	        for (int i = 0; i < tokens.length; i++) {
208	            switch (tokens[i]) {
209	                case "ST" -> tokens[i] = "STREET";
210	                case "RD" -> tokens[i] = "ROAD";
211	                case "AVE" -> tokens[i] = "AVENUE";
212	                default -> { }
213	            }
214	        }
215	        return String.join(" ", tokens);
216	    }
217	
218	    /**
219	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
220	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
221	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
222	     * empty string.
223	     *
224	     * @param value the raw value (last name or address) as submitted
225	     * @return the normalized comparison key
226	     */
227	    private String normalizeForHousehold(String value) {
228	        if (value == null) {
229	            return "";
230	        }
231	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
232	    }
233	
234	    /**
235	     * Derives the stable shared household identifier for a household, keyed on the normalized last
236	     * name and address. Because it is a pure function of those normalized keys, every owner in the
237	     * same household deterministically computes the same value. The identifier is the first 12
238	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
239	     * (the separator prevents distinct name/address pairs from colliding).
240	     *
241	     * @param lastNameKey the normalized last-name comparison key
242	     * @param addressKey  the normalized address comparison key
243	     * @return the stable household identifier
244	     */
245	    private String householdId(String lastNameKey, String addressKey) {
246	        String seed = lastNameKey + "�" + addressKey;
247	        try {
248	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
249	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
250	            StringBuilder sb = new StringBuilder(digest.length * 2);
251	            for (byte b : digest) {
252	                sb.append(String.format("%02x", b));
253	            }
254	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
255	        }
256	        catch (java.security.NoSuchAlgorithmException e) {
257	            throw new IllegalStateException("SHA-256 not available", e);
258	        }
259	    }
260	
261	    /**
262	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
263	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
264	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
265	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
266	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
267	     * is stored as {@code '+61412345678'}.
268	     *
269	     * @param telephone the raw telephone number as submitted
270	     * @return the normalized E.164 telephone number
271	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
272	     *         number (8 to 15 digits after the '+')
273	     */
274	    private String normalizeTelephone(String telephone) {
275	        String raw = telephone == null ? "" : telephone.trim();
276	        String digits = raw.replaceAll("\\D", "");
277	        String e164;
278	        if (raw.startsWith("+")) {
279	            e164 = "+" + digits;
280	        } else {
281	            if (digits.startsWith("0")) {
282	                digits = digits.substring(1);
283	            }
284	            e164 = "+61" + digits;
285	        }
286	        int digitCount = e164.length() - 1;
287	        if (digitCount < 8 || digitCount > 15) {
288	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
289	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
290	        }
291	        return e164;
292	    }
293	
294	    /**
295	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
296	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
297	     * (absent) or already valid.
298	     *
299	     * @param email the email address as submitted, or {@code null} when absent
300	     * @return the lower-cased email, or {@code null} when absent
301	     */
302	    private String normalizeEmail(String email) {
303	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
304	    }
